#include "inputs/audit_helpers.hpp"
J AlphaJ(const hyp::LayerPoint<double>&p){J h(D(p.alpha));for(int i=0;i<3;++i){h.d[i]=p.state.alpha.d[i];for(int j=0;j<3;++j)h.dd[i][j]=p.state.alpha.dd[i][j];}return h;}
J Power(const J&x,int m){J q(D(1));for(int i=0;i<m;++i)q=q*x;return q;}
Jet Initial(const hyp::LayerPoint<double>&p,int which,int m){auto u=Lift(p.state);auto O=OmegaJ(p);if(which==0){for(int i=0;i<3;++i)Seed(u,4+i,Linear(Power(O,m)*Unit(p,i)));}
 if(which==1){const J f=J(D(1))+J(D(.25))*O+J(D(.5))*Unit(p,1);Seed(u,0,Linear(AlphaJ(p)*f));for(int i=0;i<3;++i){J b(D(p.state.beta.value[i]));for(int j=0;j<3;++j){b.d[j]=p.state.beta.d[j][i];for(int k=0;k<3;++k)b.dd[j][k]=p.state.beta.dd[j][k][i];}Seed(u,4+i,Linear(b*f));}}
 if(which==2)return Witness(p);Consistent(u);return u;}
Jet FirstRHSField(const hyp::LayerPoint<double>&p,int m,double a,double sigma){auto u=Lift(p.state);J r(D(p.radius));for(int i=0;i<3;++i){r.d[i]=i==0?1:0;for(int j=0;j<3;++j)r.dd[i][j]=((i==j?1.:0.)-(i==0&&j==0?1.:0.))/p.radius;}const J O=OmegaJ(p),h=AlphaJ(p),b=Power(O,m),bm=Power(O,m-1),bl=Power(O,m-2);
 const J bp=J(D(-double(m)/a))*r*bm,q=J(D(2))*(bp-b/r);
 const J af=J(D(3/a))*h*r*bm,bf=J(D((m-2*sigma)/(a*a)))*r*r*bm+(J(D(-6/a))+J(D(2/(a*a)))*r*r/h)*b;
 const J cf=J(D(2*(m-3)/(3*a)))*r*bm-J(D(4./3.))*b/r;
 const J lf=J(D(4.*m*(m-1)/(3*a*a)))*r*r*bl-J(D(4.*m/a))*bm-J(D(8./3.))*b/(r*r);
 Seed(u,0,Linear(af));Seed(u,1,Linear(cf));const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};
 for(int i=0;i<3;++i){Seed(u,4+i,Linear(bf*Unit(p,i)));Seed(u,17+i,Linear(lf*Unit(p,i)));}
 for(int z=0;z<5;++z){const int i=ti[z],j=tj[z];Seed(u,7+z,Linear(q*(Unit(p,i)*Unit(p,j)-J(D(i==j?1./3.:0.)))));}
 Consistent(u);return u;}
std::array<double,20> Values(const Jet&u){std::array<double,20>v{};v[0]=u.alpha.value.d;v[1]=u.chi.value.d;v[2]=u.trace.value.d;v[3]=u.theta.value.d;const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};for(int i=0;i<3;++i){v[4+i]=u.beta.value[i].d;v[17+i]=u.lambda.value[i].d;}for(int i=0;i<5;++i){v[7+i]=u.metric.g[ti[i]][tj[i]].d;v[12+i]=u.a.k[ti[i]][tj[i]].d;}return v;}
double N1(const Jet&u,const hyp::LayerPoint<double>&p,double a){const auto g=hyp::Geometry(u.metric);const auto o=Omega(u,p);D dG{};for(int i=0;i<3;++i)for(int j=0;j<3;++j){D dinv{};for(int l=0;l<3;++l)for(int k=0;k<3;++k)dinv-=g.inverse[i][l]*u.metric.dg[0][l][k]*g.inverse[k][j];dG+=(u.chi.d[0]*g.inverse[i][j]+u.chi.value*dinv)*D(p.domega[i]*p.domega[j])+u.chi.value*g.inverse[i][j]*D(p.omega_hessian[0][i]*p.domega[j]+p.domega[i]*p.omega_hessian[0][j]);}return -a*(dG-D(2)*o.normal*o.dnormal[0]).d;}
std::array<double,4> FourRegularity(const Jet&u,const hyp::LayerPoint<double>&p,double sigma){const auto o=Omega(u,p);hyp::Z4cRHS<D>f{};if(!hyp::AssembleInterior(hyp::ConformalRHS(u,o,D(10)/u.alpha.value,D(0)),D(p.omega),f))throw std::runtime_error("geometry invalid");hyp::LayerGaugeParameters gp;gp.scri_lapse_damping=-3/p.k_physical;hyp::GaugeRHS<D>gauge{};if(!qnf::Assemble(qnf::Gauge(Reference(p),u,gp,{.85,.95,sigma,true}),D(p.omega),gauge))throw std::runtime_error("gauge invalid");
 const auto b=hyp::PenroseMetric(u.metric,u.chi);const auto bg=hyp::Geometry(b);const D alpha=u.alpha.value;D g[4][4]{},inv[4][4]{},dg[4][4][4]{},bd[4][3][3]{};
 for(int i=0;i<3;++i)for(int j=0;j<3;++j){g[i+1][j+1]=b.g[i][j];inv[i+1][j+1]=bg.inverse[i][j]-u.beta.value[i]*u.beta.value[j]/(alpha*alpha);bd[0][i][j]=f.metric[i][j]/u.chi.value-u.metric.g[i][j]*f.chi/(u.chi.value*u.chi.value);for(int z=0;z<3;++z)bd[z+1][i][j]=b.dg[z][i][j];}
 g[0][0]=-alpha*alpha;inv[0][0]=-D(1)/(alpha*alpha);for(int i=0;i<3;++i){inv[0][i+1]=inv[i+1][0]=u.beta.value[i]/(alpha*alpha);for(int j=0;j<3;++j){g[0][i+1]+=b.g[i][j]*u.beta.value[j];g[0][0]+=b.g[i][j]*u.beta.value[i]*u.beta.value[j];}g[i+1][0]=g[0][i+1];}
 for(int z=0;z<4;++z){D da=z==0?gauge.alpha:u.alpha.d[z-1];dg[z][0][0]=-D(2)*alpha*da;for(int i=0;i<3;++i)for(int j=0;j<3;++j){D dbi=z==0?gauge.beta[i]:u.beta.d[z-1][i],dbj=z==0?gauge.beta[j]:u.beta.d[z-1][j];dg[z][i+1][j+1]=bd[z][i][j];dg[z][0][i+1]+=bd[z][i][j]*u.beta.value[j]+b.g[i][j]*dbj;dg[z][0][0]+=bd[z][i][j]*u.beta.value[i]*u.beta.value[j]+D(2)*b.g[i][j]*u.beta.value[j]*dbi;}for(int i=0;i<3;++i)dg[z][i+1][0]=dg[z][0][i+1];}
 D H[4][4]{},box{},N{};for(int aa=0;aa<4;++aa)for(int bb=0;bb<4;++bb){if(aa&&bb)H[aa][bb]=p.omega_hessian[aa-1][bb-1];for(int i=0;i<3;++i)for(int l=0;l<4;++l)H[aa][bb]-=D(.5*p.domega[i])*inv[i+1][l]*(dg[aa][l][bb]+dg[bb][l][aa]-dg[l][aa][bb]);box+=inv[aa][bb]*H[aa][bb];}for(int i=0;i<3;++i)for(int j=0;j<3;++j)N+=inv[i+1][j+1]*D(p.domega[i]*p.domega[j]);double shear=0;for(int aa=0;aa<4;++aa)for(int bb=0;bb<4;++bb)shear=std::max(shear,std::abs((H[aa][bb]-g[aa][bb]*box/D(4)).d/p.omega));return {box.d/p.omega,N.d/(p.omega*p.omega),shear,(-D(6)*box/D(p.omega)+D(12)*N/D(p.omega*p.omega)).d};}
int main(){std::cout<<std::setprecision(17)<<"{\"rows\":[";bool first=true;double C=0,S=0,field_error=0,box_error=0,shear_bound=0;int initial=0;
 for(double a:{.5,.75,1.,2.})for(double sigma:{0.,3.,5.})for(int which:{0,1,2})for(int m:(which==0?std::initializer_list<int>{2,3,4}:std::initializer_list<int>{2})){hyp::LayerReference<double>ref(1,a,{true,.05,.95});for(double oo:{0.,.004,.002,.001,.0005,.00025,.0001,.00001}){auto p=ref.At(std::sqrt(1-2*a*oo),0,0);auto u=Initial(p,which,m);const auto f=Parts(p,u,10,sigma,true);const auto cc=Constraints(u,p);for(double c:cc)C=std::max(C,std::abs(c));if(p.omega==0){for(auto s:f.s)S=std::max(S,std::abs(s.d));++initial;if(which==0){const auto field=FirstRHSField(p,m,a,sigma);const auto next=Parts(p,field,10,sigma,true);}}
 if(!first)std::cout<<',';first=false;std::cout<<"{\"a\":"<<a<<",\"sigma\":"<<sigma<<",\"which\":"<<which<<",\"m\":"<<m<<",\"Omega\":"<<p.omega<<",\"Npert\":"<<qnf::NullDifference(Reference(p),u).d<<",\"Qnumpert\":"<<u.trace.value.d-3*Omega(u,p).normal.d<<",\"S\":";Print(f.s);std::cout<<",\"C\":[";for(int i=0;i<8;++i)std::cout<<(i?",":"")<<cc[i];std::cout<<']';if(which==0&&p.omega==0){const auto field=FirstRHSField(p,m,a,sigma);const auto next=Parts(p,field,10,sigma,true);std::cout<<",\"next_R0\":";Print(next.s);std::cout<<",\"next_N1\":"<<N1(field,p,a);}
 if(p.omega>0){std::array<D,20>F{};for(int i=0;i<20;++i)F[i]=f.r[i]+f.s[i]/D(p.omega);if(which==0){const auto reg=FourRegularity(u,p,sigma);box_error=std::max(box_error,std::abs(reg[0]-sigma*reg[1]));shear_bound=std::max(shear_bound,reg[2]);std::cout<<",\"initial_4D_regular\":["<<reg[0]<<','<<reg[1]<<','<<reg[2]<<','<<reg[3]<<']';const auto fv=Values(FirstRHSField(p,m,a,sigma));for(int i=0;i<20;++i)field_error=std::max(field_error,std::abs(F[i].d-fv[i]));}const auto om=Omega(u,p);const double wdot=-(p.domega[0]*F[4].d+om.normal.v*F[0].d)/p.alpha;
 const double Ndot=(F[1].d-F[7].d)*p.domega[0]*p.domega[0]-2*om.normal.v*wdot;std::cout<<",\"F\":";Print(F);std::cout<<",\"Ndot\":"<<Ndot<<",\"Qnumdot\":"<<F[2].d-3*wdot;}
 std::cout<<'}';}}
 std::cout<<"],\"summary\":{\"initial_boundary_controls\":"<<initial<<",\"initial_constraints_error\":"<<C<<",\"initial_R0_error\":"<<S<<",\"exact_radial_RHS_field_error\":"<<field_error<<",\"initial_4D_Box_identity_error\":"<<box_error<<",\"initial_coordinate_shear_over_Omega_max\":"<<shear_bound<<"}}\n";
}
